genericProducts.push(...buildExtraSeedProducts(genericProducts));

// Pozycje dodane jako codzienne produkty sklepowe mają jawnie wskazane źródło referencyjne.
const everydayIds = new Set(everydayRows.map(row => norm(row[0])));
for (const product of genericProducts) {
  if (!everydayIds.has(product.id)) continue;
  product.source = 'Szacunek dla kategorii ogólnej; USDA FDC i tabele NIZP PZH służą jako źródła odniesienia';
  product.sourceUrl = 'https://fdc.nal.usda.gov/';
  product.dataNote = 'Wartość orientacyjna dla ogólnej kategorii, nie wynik dopasowania do konkretnego rekordu USDA ani polskiej karty SKU. Nie należy traktować jej jako deklaracji sklepu lub producenta; nadrzędna jest etykieta opakowania.';
}

// Lidl i Kaufland publikują nazwy asortymentu, ale ich karty produktów
// nie zawierają pełnych tabel wartości odżywczych. Wartości poniżej są więc
// orientacyjne dla danego typu produktu, a nie deklaracją konkretnego SKU.
const ASSORTMENT_NOTE='Nazwa i asortyment z oficjalnej strony sklepu. Wartości orientacyjne dla tego typu produktu — sklep nie publikuje tabeli odżywczej; sprawdź etykietę, jeśli jest dostępna.';
