// Poprawione nazwy starszych, ogólnych wpisów napojowych.
const legacyDrinkNames = {
  'woda-kokosowa-unsweetened':'Woda kokosowa bez dodatku cukru',
  'herbata-mrozona-unsweetened':'Herbata mrożona bez cukru',
  'kakao-woda-unsweetened':'Kakao na wodzie bez cukru',
  'kakao-woda':'Kakao na wodzie z cukrem',
  'pantry-oat-latte':'Kawa z napojem owsianym',
  'pantry-cocoa-drink':'Kakao na mleku',
  'coffee-milk':'Kawa z mlekiem 2% (proporcja 60:40)',
  'tea':'Herbata parzona'
};
for (const p of products) {
  const oldName = String(p.name || '').trim().replace(/\s+/g, ' ');
  if (canonicalDrinkNames[p.id]) p.name = canonicalDrinkNames[p.id];
  else if (p.store === 'Ogólne' && legacyDrinkNames[p.id]) p.name = legacyDrinkNames[p.id];
  else {
    // W nazwach produktów sklepowych marka i gramatura są już osobnymi polami.
    let name = oldName.replace(/\s*[—–-]\s*asortyment\s+(?:Lidl|Biedronka|Kaufland|Carrefour)\s*$/i, '').trim();
    const brand = String(p.brand || '').trim();
    if (brand && p.store !== 'Ogólne' && name.toLocaleLowerCase('pl').startsWith((brand + ' ').toLocaleLowerCase('pl'))) {
      name = name.slice(brand.length).trim();
    }
    // Usuń gramaturę opakowania z nazwy, bo jest w unitWeight.
    if (p.store !== 'Ogólne' && p.unitWeight != null) {
      name = name.replace(/\s+\d+(?:[,.]\d+)?\s*(?:g|kg|ml|l)\s*$/i, '').trim();
    }
    // Usuń białe znaki i kropki-łączniki używane wcześniej jak ozdobniki.
    name = name.replace(/\s*·\s*/g, ', ').replace(/\s+/g, ' ').trim();
    if (name) p.name = name.charAt(0).toLocaleUpperCase('pl') + name.slice(1);
  }
  if (oldName && oldName !== p.name) {
    p.aliases = [...new Set([...(Array.isArray(p.aliases) ? p.aliases : []), oldName])];
  }
}

// Ujednolicenie nazw produktów domowych i pozycji convenience.
// Informacja, że rekord jest szacunkiem/recepturą, pozostaje w sourceKind,
// nutritionStatus i dataNote — nie zaś w nazwie wyświetlanej użytkownikowi.
const normalizedNameAudit = { homemadeSuffixRemoved: 0, convenienceSuffixRemoved: 0, cinemaDescriptorRemoved: 0, duplicateGenericColaRenamed: 0 };
for (const p of products) {
  const before = String(p.name || '');
  let name = before
    .replace(/\s*,\s*domowe\s*$/i, '')
    .replace(/\s*[—–-]\s*typowy produkt convenience\s*$/i, '')
    .replace(/\s*[—–-]\s*typowa porcja\s*$/i, '')
    .replace(/\s*[—–-]\s*chipsy tortilla\s*$/i, '')
    .replace(/\s*[—–-]\s*komponent popcorn\s*$/i, '')
    .replace(/\s*[—–-]\s*gotowa\s*$/i, '')
    .replace(/\s+/g, ' ')
    .trim();
  if (name !== before) {
    if (/\s*,\s*domowe\s*$/i.test(before)) normalizedNameAudit.homemadeSuffixRemoved++;
    if (/\s*[—–-]\s*typowy produkt convenience\s*$/i.test(before) || /\s*[—–-]\s*typowa porcja\s*$/i.test(before)) normalizedNameAudit.convenienceSuffixRemoved++;
    if (/\s*[—–-]\s*(chipsy tortilla|komponent popcorn)\s*$/i.test(before)) normalizedNameAudit.cinemaDescriptorRemoved++;
    p.aliases = [...new Set([...(Array.isArray(p.aliases) ? p.aliases : []), before])];
    p.name = name;
  }
}
// Rozróżnij neutralny produkt typu cola od konkretnej marki Coca-Cola.
const genericColaZero = products.find(p => p.id === 'og-lne:extra:cola-zero');
if (genericColaZero && genericColaZero.name === 'Cola bez cukru') {
  genericColaZero.aliases = [...new Set([...(genericColaZero.aliases || []), genericColaZero.name])];
  genericColaZero.name = 'Napój typu cola bez cukru';
  normalizedNameAudit.duplicateGenericColaRenamed++;
}

// Ujednolicenie oczywistych wariantów nazw kategorii.
for (const p of products) {
  if (p.category === 'Pieczywo i wypieki') p.category = 'Pieczywo';
  if (p.category === 'Mięso i drób') p.category = 'Mięso i ryby';
  if (p.category === 'Mrożone') p.category = 'Mrożonki';
  if (p.category === 'Dania mrożone') p.category = 'Mrożonki';
  if (p.category === 'Mięso i wędliny' || p.category === 'Wędliny i kiełbasy' || p.category === 'Mięso i ryby') p.category = 'Mięso, ryby i wędliny';
  if (p.category === 'Słodkie wypieki' || p.category === 'Słodycze') p.category = 'Słodycze i wypieki';
}

// Dokładne duplikaty typowych pozycji sklepów (ta sama nazwa, gramatura i te
// same kcal/makro/błonnik) łączymy w jeden profil kategorii. Nie łączymy SKU
// z odmienną marką lub odmiennymi wartościami.
const duplicateGroups = new Map();
const duplicateKey = p => [
  String(p.name || '').toLocaleLowerCase('pl').replace(/\s+/g, ' ').trim(),
  p.category, p.unitWeight,
  p.kcal100, p.protein100, p.fat100, p.carbs100, p.fiber100
].join('|');
for (const p of products) {
  if (p.sourceKind !== 'retailer-assortment-reference' || p.store === 'Ogólne') continue;
  const key = duplicateKey(p);
  if (!duplicateGroups.has(key)) duplicateGroups.set(key, []);
  duplicateGroups.get(key).push(p);
}
const duplicateIdsToRemove = new Set();
for (const group of duplicateGroups.values()) {
  if (group.length < 2) continue;
  const stores = [...new Set(group.map(p => p.store).filter(Boolean))];
  const primary = group[0];
  if (stores.length > 1) {
    primary.availableAt = stores;
    primary.store = 'Ogólne';
    primary.brand = '';
    primary.source = `Katalogi asortymentu: ${stores.join(', ')} · wspólny profil kategorii`;
    primary.dataNote = `${primary.dataNote || ''} Identyczny profil szacunkowy występował w katalogach ${stores.join(' i ')}; scalono go do jednego rekordu, ponieważ nie były to odrębne etykiety SKU.`.trim();
    primary.aliases = [...new Set([...(primary.aliases || []), ...stores])];
    primary.nutritionMethod = 'Wspólny szacunek dla tej samej kategorii produktu; wpisy asortymentowe z identycznymi wartościami scalono. Nie jest to etykieta producenta.';
  }
  for (const duplicate of group.slice(1)) duplicateIdsToRemove.add(duplicate.id);
}
if (duplicateIdsToRemove.size) {
  for (let i = products.length - 1; i >= 0; i--) {
    if (duplicateIdsToRemove.has(products[i].id)) products.splice(i, 1);
  }
}

// Scal starsze, ogólne wpisy napojów z nowszymi, lepiej opisanymi rekordami.
// Dane odżywcze nie są uśredniane ani zmieniane: zachowujemy profil rekordu docelowego.
const productIdRedirects = {};
const consolidatedLegacyDrinkRows = [];
function consolidateProduct(sourceId, targetId, extraAliases = [], excludedAliases = []) {
  const sourceIndex = products.findIndex(p => p.id === sourceId);
  const target = products.find(p => p.id === targetId);
  if (sourceIndex < 0 || !target) return;
  const source = products[sourceIndex];
  const excluded = new Set(excludedAliases.map(v => String(v).toLocaleLowerCase('pl')));
  const carried = [source.name, ...(source.aliases || []), ...extraAliases]
    .filter(Boolean)
    .filter(v => !excluded.has(String(v).toLocaleLowerCase('pl')));
  target.aliases = [...new Set([...(target.aliases || []), ...carried])];
  productIdRedirects[sourceId] = targetId;
  consolidatedLegacyDrinkRows.push({ removedId: sourceId, targetId });
  products.splice(sourceIndex, 1);
}
consolidateProduct('kawa-czarna', 'drink-home:coffee-black-filter', ['kawa czarna bez cukru'], ['espresso','americano']);
consolidateProduct('tea', 'drink-home:tea-black', ['herbata parzona','herbata bez cukru']);
consolidateProduct('pantry-cocoa-drink', 'cocoa', ['kakao na mleku']);
consolidateProduct('pantry-oat-latte', 'drink-home:coffee-latte-oat', ['kawa z napojem owsianym','latte na napoju owsianym']);
consolidateProduct('og-lne:extra:cola-regular', 'cola', ['cola słodzona']);
consolidateProduct('pantry-cola-zero', 'cola-zero', ['napój typu cola zero']);
consolidateProduct('og-lne:extra:cola-zero', 'drink:coca-cola-zero', ['cola bez cukru','cola zero']);
// Usuń aliasy, które przypisywały espresso i americano do kawy filtrowanej.
const espressoProduct = products.find(p => p.id === 'drink-home:coffee-espresso');
const americanoProduct = products.find(p => p.id === 'drink-home:coffee-americano');
if (espressoProduct) espressoProduct.aliases = [...new Set([...(espressoProduct.aliases || []), 'espresso bez cukru'])];
if (americanoProduct) americanoProduct.aliases = [...new Set([...(americanoProduct.aliases || []), 'americano bez cukru'])];

// Usuń techniczne nazwy katalogowe, które mogły pozostać w źródłach sklepowych.
for (const p of products) {
  p.name = String(p.name || '').replace(/\s*[—–-]\s*asortyment\s+(?:Lidl|Biedronka|Kaufland|Carrefour)\s*$/i, '').trim();
  p.aliases = [...new Set((Array.isArray(p.aliases) ? p.aliases : []).filter(Boolean))];
}

productCatalogInfo.count = products.length;
productCatalogInfo.generic = products.filter(p => p.store === 'Ogólne').length;
productCatalogInfo.storeCount = products.length - productCatalogInfo.generic;
productCatalogInfo.biedronka = products.filter(p => p.store === 'Biedronka').length;
productCatalogInfo.lidl = products.filter(p => p.store === 'Lidl').length;
productCatalogInfo.kaufland = products.filter(p => p.store === 'Kaufland').length;
productCatalogInfo.carrefour = products.filter(p => p.store === 'Carrefour').length;
productCatalogInfo.otherStores = Object.fromEntries([...new Set(products.map(p => p.store))]
  .filter(store => !['Ogólne','Biedronka','Lidl','Kaufland','Carrefour'].includes(store))
  .map(store => [store, products.filter(p => p.store === store).length]));
productCatalogInfo.beverageCount = products.filter(p => p.category === 'Napoje').length;
productCatalogInfo.beverageAdditions = products.filter(p => p.id.startsWith('drink:') || p.id.startsWith('drink-home:') || p.id.startsWith('drink-powder:')).length;
productCatalogInfo.cleanup = {
  generatedRetailerCopiesRemoved: 3000,
  redundantDilutedDrinkRowsRemoved: 9,
  exactRetailerDuplicatesRemoved: duplicateIdsToRemove.size,
  duplicateProfilesMerged: [...duplicateGroups.values()].filter(group => group.length > 1).length,
  namingStandardization: 'Marka i gramatura są przechowywane osobno; nazwa opisuje sam produkt. Dawne pełne nazwy pozostają w aliases.',
  categoryStandardization: {'Pieczywo i wypieki':'Pieczywo','Mięso i drób':'Mięso, ryby i wędliny','Mięso i ryby':'Mięso, ryby i wędliny','Mięso i wędliny':'Mięso, ryby i wędliny','Wędliny i kiełbasy':'Mięso, ryby i wędliny','Mrożone':'Mrożonki','Dania mrożone':'Mrożonki','Słodkie wypieki':'Słodycze i wypieki','Słodycze':'Słodycze i wypieki'}
};
productCatalogInfo.cleanup.displayNameStandardization = normalizedNameAudit;
productCatalogInfo.cleanup.legacyDrinkRowsConsolidated = consolidatedLegacyDrinkRows.length;
productCatalogInfo.idRedirects = productIdRedirects;
productCatalogInfo.cleanup.categoriesUnified = ['Mięso, ryby i wędliny', 'Słodycze i wypieki', 'Mrożonki'];
productCatalogInfo.version = '2026-11-23.6';
productCatalogInfo.auditDate = '2026-11-23';
productCatalogInfo.note = 'Katalog nie zawiera sztucznych kopii ogólnych produktów przypisanych do każdej sieci. Produkty sklepowe pozostają odrębne tylko wtedy, gdy mają rzeczywistą odrębną markę, SKU, etykietę lub skład. Nazwy nie zawierają technicznych etykiet szacowania ani powtarzanej gramatury; marka i gramatura są osobnymi polami. Wartości żywieniowe nie zostały zmienione przez standaryzację nazw i kategorii.';


