const expansionProductIds = new Set(products.map(p => p.id));
const expansionProductNames = new Set(products.map(p => String(p.name||'').toLocaleLowerCase('pl').replace(/\s+/g,' ').trim()));
for (const p of expansionProducts) {
  if (expansionProductIds.has(p.id)) throw new Error(`Duplicate product id in expansion: ${p.id}`);
  const k = String(p.name||'').toLocaleLowerCase('pl').replace(/\s+/g,' ').trim();
  if (expansionProductNames.has(k)) throw new Error(`Duplicate product name in expansion: ${p.name}`);
  expansionProductIds.add(p.id); expansionProductNames.add(k);
  products.push(p);
}
productCatalogInfo.count = products.length;
productCatalogInfo.generic = products.filter(p=>p.store==='Ogólne').length;
productCatalogInfo.storeCount = products.length-productCatalogInfo.generic;
productCatalogInfo.categoryCounts = Object.fromEntries([...new Set(products.map(p=>p.category))].sort().map(c=>[c,products.filter(p=>p.category===c).length]));
productCatalogInfo.expansion = {added: expansionProducts.length, sourceKind: 'generic-reference', confidence: 'low; category-level estimates, not item-specific labels', candidatesReviewed: 1544, earlyNameAliasDuplicatesRejected: 129, similarOrSemanticallyDuplicateCandidatesRejected: 244, extraManualDeduplication: 2, date: '2026-11-23'};
productCatalogInfo.version = '2026-11-23.7';
